import{_ as i,o as a,c as t,a4 as e}from"./chunks/framework.BMj-uaUw.js";const c=JSON.parse('{"title":"开发环境准备","description":"","frontmatter":{},"headers":[{"level":2,"title":"需要装什么","slug":"需要装什么","link":"#需要装什么","children":[]},{"level":2,"title":"第一步：安装 Node.js","slug":"第一步-安装-node-js","link":"#第一步-安装-node-js","children":[{"level":3,"title":"macOS 与 Linux","slug":"macos-与-linux","link":"#macos-与-linux","children":[]},{"level":3,"title":"Windows","slug":"windows","link":"#windows","children":[]}]},{"level":2,"title":"第二步：安装 pnpm","slug":"第二步-安装-pnpm","link":"#第二步-安装-pnpm","children":[]},{"level":2,"title":"第三步：安装编辑器与插件","slug":"第三步-安装编辑器与插件","link":"#第三步-安装编辑器与插件","children":[]},{"level":2,"title":"第四步：浏览器准备","slug":"第四步-浏览器准备","link":"#第四步-浏览器准备","children":[]},{"level":2,"title":"第五步：Git 基础配置","slug":"第五步-git-基础配置","link":"#第五步-git-基础配置","children":[]},{"level":2,"title":"第六步（可选）：用户端需要的额外工具","slug":"第六步-可选-用户端需要的额外工具","link":"#第六步-可选-用户端需要的额外工具","children":[]},{"level":2,"title":"环境自检清单","slug":"环境自检清单","link":"#环境自检清单","children":[]},{"level":2,"title":"常见问题","slug":"常见问题","link":"#常见问题","children":[]},{"level":2,"title":"下一步","slug":"下一步","link":"#下一步","children":[]}],"relativePath":"guide/environment.md","filePath":"guide/environment.md","lastUpdated":1789500889000}'),n={name:"guide/environment.md"};function l(p,s,d,h,o,r){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="开发环境准备" tabindex="-1">开发环境准备 <a class="header-anchor" href="#开发环境准备" aria-label="Permalink to &quot;开发环境准备&quot;">​</a></h1><p>这一页的目标很明确：<strong>在干净机器上把前端开发环境装好，并且能通过自检。</strong></p><p>装环境失败是新手最常见的卡点，而且失败的体验很糟 —— 报错信息看不懂，不知道哪一步错了。 所以下面每一步都附了<strong>验证命令</strong>。命令输出对得上，才继续下一步。</p><h2 id="需要装什么" tabindex="-1">需要装什么 <a class="header-anchor" href="#需要装什么" aria-label="Permalink to &quot;需要装什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>作用</th><th>版本要求</th></tr></thead><tbody><tr><td>Node.js</td><td>前端工具链的运行基础</td><td>24 LTS（最低 20.19）</td></tr><tr><td>pnpm</td><td>包管理器，负责装依赖</td><td>12.x</td></tr><tr><td>编辑器</td><td>写代码的地方，推荐 VSCode</td><td>最新版</td></tr><tr><td>浏览器</td><td>运行与调试页面，推荐 Chrome</td><td>最新版</td></tr><tr><td>Git</td><td>版本管理</td><td>2.40 以上</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>文中版本为编写时核对的结果。Node 用 <strong>24 LTS（Krypton）</strong>，它的维护周期到 2028 年。 Node 22 是维护版，也能跑，但不建议新环境再用。<strong>不要用 Current 版本做课程作业</strong> —— 它的更新节奏太快，教学环境容易出不一致。</p></div><h2 id="第一步-安装-node-js" tabindex="-1">第一步：安装 Node.js <a class="header-anchor" href="#第一步-安装-node-js" aria-label="Permalink to &quot;第一步：安装 Node.js&quot;">​</a></h2><p><strong>不要直接去官网下载安装包。</strong> 原因是你迟早需要同时保留几个 Node 版本： 项目 A 要 Node 20，项目 B 要 Node 24，直接装会互相覆盖。用版本管理工具才是正解。</p><h3 id="macos-与-linux" tabindex="-1">macOS 与 Linux <a class="header-anchor" href="#macos-与-linux" aria-label="Permalink to &quot;macOS 与 Linux&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 用 Homebrew 装 fnm（一个快速的 Node 版本管理器）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fnm</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 让 shell 认识 fnm（zsh 用户）</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;eval &quot;$(fnm env --use-on-cd)&quot;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.zshrc</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.zshrc</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 装并切换到 Node 24</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fnm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fnm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span></span></code></pre></div><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 用 winget 装 fnm</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">winget install Schniz.fnm</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 新开一个终端后，装并切换到 Node 24</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fnm install </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">24</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fnm </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">default</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span></span></code></pre></div><details class="details custom-block"><summary>不想用版本管理器？也可以装 nvm</summary><p>nvm 更老牌，资料更多，但速度比 fnm 慢。 macOS 与 Linux 用 <a href="https://github.com/nvm-sh/nvm" target="_blank" rel="noreferrer">nvm-sh</a>，Windows 用 <a href="https://github.com/coreybutler/nvm-windows" target="_blank" rel="noreferrer">nvm-windows</a>。 命令大同小异，把 <code>fnm install 24</code> 换成 <code>nvm install 24 &amp;&amp; nvm use 24</code> 即可。</p></details><p><strong>验证</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 期望输出 v24.x.x</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 期望输出 11.x 或更高</span></span></code></pre></div><p>输出对得上，第一步完成。</p><h2 id="第二步-安装-pnpm" tabindex="-1">第二步：安装 pnpm <a class="header-anchor" href="#第二步-安装-pnpm" aria-label="Permalink to &quot;第二步：安装 pnpm&quot;">​</a></h2><p>pnpm 比 npm 快得多，而且它用硬链接共享依赖 —— 十个项目用同一个版本的 Vue， 磁盘上只存一份。对要反复建工程的学生来说，这个差别很实在。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm</span></span></code></pre></div><p><strong>验证</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 期望输出 12.x</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Windows 上遇到&quot;权限不足&quot;</p><p>用管理员身份打开 PowerShell 再执行。或者改用 Node 自带的 corepack：<code>corepack enable pnpm</code>。</p></div><details class="details custom-block"><summary>为什么不用 npm？</summary><p>npm 能用，但有两个现实问题：一是它把依赖平铺在 <code>node_modules</code> 里，同一个包的不同版本会重复存很多份； 二是它对&quot;幽灵依赖&quot;（用了没声明的包）很宽容，本地能跑、别人机器上就报 <code>Cannot find module</code>。 pnpm 的严格模式会提前把这些错误暴露出来，这在教学里是好事。</p></details><h2 id="第三步-安装编辑器与插件" tabindex="-1">第三步：安装编辑器与插件 <a class="header-anchor" href="#第三步-安装编辑器与插件" aria-label="Permalink to &quot;第三步：安装编辑器与插件&quot;">​</a></h2><p>推荐 VSCode。装完后<strong>必须</strong>装这几个扩展，否则后面的规范章节会缺工具：</p><table tabindex="0"><thead><tr><th>扩展</th><th>作用</th></tr></thead><tbody><tr><td>Vue - Official</td><td>Vue 单文件组件的语法高亮、类型提示、格式化</td></tr><tr><td>ESLint</td><td>在编辑器里直接标出代码问题</td></tr><tr><td>Prettier - Code formatter</td><td>保存时自动格式化</td></tr><tr><td>EditorConfig for VS Code</td><td>统一缩进与换行符</td></tr></tbody></table><p>装完把这两项打开（<code>设置</code> → 搜索）：</p><ul><li><strong>Editor: Format On Save</strong> —— 勾选。保存即格式化，省掉一堆格式争论。</li><li><strong>Files: Eol</strong> —— 设为 <code>\\n</code>。避免 Windows 和 macOS 之间因为换行符产生整文件级的假冲突。</li></ul><h2 id="第四步-浏览器准备" tabindex="-1">第四步：浏览器准备 <a class="header-anchor" href="#第四步-浏览器准备" aria-label="Permalink to &quot;第四步：浏览器准备&quot;">​</a></h2><p>用 Chrome 或 Edge，按 <code>F12</code> 打开开发者工具。这几个面板你会反复用到：</p><table tabindex="0"><thead><tr><th>面板</th><th>什么时候用</th></tr></thead><tbody><tr><td>Console</td><td>看报错、临时执行一段代码</td></tr><tr><td>Elements</td><td>看 DOM 结构和最终生效的 CSS</td></tr><tr><td>Network</td><td>看接口请求的地址、参数、状态码、响应体</td></tr><tr><td>Application</td><td>看 localStorage 里的登录凭证</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">装一个扩展：Vue.js devtools</p><p>它能让你直接看到组件的层级、每个组件当前的 props 与状态。 排查&quot;数据传丢了&quot;这类问题时，比 <code>console.log</code> 快得多。</p></div><h2 id="第五步-git-基础配置" tabindex="-1">第五步：Git 基础配置 <a class="header-anchor" href="#第五步-git-基础配置" aria-label="Permalink to &quot;第五步：Git 基础配置&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;你的姓名&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;你的邮箱&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init.defaultBranch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core.autocrlf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> input</span></span></code></pre></div><p>最后一条是换行符设置：提交时统一转成 <code>\\n</code>，检出时不转换。<strong>团队协作时这一条能省掉大量假冲突。</strong></p><p><strong>验证</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -20</span></span></code></pre></div><h2 id="第六步-可选-用户端需要的额外工具" tabindex="-1">第六步（可选）：用户端需要的额外工具 <a class="header-anchor" href="#第六步-可选-用户端需要的额外工具" aria-label="Permalink to &quot;第六步（可选）：用户端需要的额外工具&quot;">​</a></h2><p>只做管理端的话，前面五步就够了。要做 <a href="/frontend-engineering-course/mobile/">uni-app 用户端</a> 的话，再补两样。</p><p><strong>一、微信开发者工具</strong></p><p><code>pnpm dev:mp-weixin</code> 只负责把代码编译成小程序产物，产物本身不会自己跑起来 —— 需要微信开发者工具去打开它，才能预览和真机调试。</p><p>到<a href="https://developers.weixin.qq.com/miniprogram/dev/devtools/download.html" target="_blank" rel="noreferrer">微信官方文档</a> 下载对应系统的<strong>稳定版</strong>，装完用微信扫码登录。</p><p><strong>二、一个测试用的小程序 AppID</strong></p><p>到<a href="https://mp.weixin.qq.com/" target="_blank" rel="noreferrer">微信公众平台</a>注册一个小程序账号，拿到 <code>AppID</code>，填进 <code>src/manifest.json</code> 的 <code>mp-weixin.appid</code>。没有 AppID 也能在开发者工具里打开， 但<strong>真机预览和上传体验版都需要它</strong>。</p><div class="warning custom-block"><p class="custom-block-title">只在需要的时候装</p><p>这两样东西加起来几百 MB，而且不做用户端的话完全用不上。建议先把管理端做完， 确定要做第二端了再装。</p></div><h2 id="环境自检清单" tabindex="-1">环境自检清单 <a class="header-anchor" href="#环境自检清单" aria-label="Permalink to &quot;环境自检清单&quot;">​</a></h2><p>把下面每一项都跑一遍，全部打勾才算环境就绪：</p><ul><li>[ ] <code>node -v</code> 输出 v24 开头</li><li>[ ] <code>npm -v</code> 输出 11 以上</li><li>[ ] <code>pnpm -v</code> 输出 12 开头</li><li>[ ] VSCode 已装 4 个扩展，且保存时能自动格式化</li><li>[ ] 浏览器按 F12 能打开开发者工具，Console 面板能输入 <code>1 + 1</code> 得到 <code>2</code></li><li>[ ] <code>git config --global user.name</code> 能输出你的名字</li><li>[ ] 能创建一个测试仓库并成功提交一次</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><details class="details custom-block"><summary>提示 &quot;command not found: node&quot;</summary><p>说明 Node 没装好，或者环境变量没生效。<strong>先关闭终端再重新打开</strong> —— 大多数情况是这个问题。 还不行就检查 fnm 的初始化语句是否写进了正确的配置文件（zsh 是 <code>~/.zshrc</code>，bash 是 <code>~/.bash_profile</code>）。</p></details><details class="details custom-block"><summary>提示 &quot;无法加载文件，因为在此系统上禁止运行脚本&quot;（Windows）</summary><p>PowerShell 的执行策略太严。以管理员身份运行 <code>Set-ExecutionPolicy RemoteSigned -Scope CurrentUser</code>， 输入 <code>Y</code> 确认即可。</p></details><details class="details custom-block"><summary>pnpm install 卡住不动</summary><p>大概率是网络问题。换镜像源后重试：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://registry.npmmirror.com</span></span></code></pre></div></details><details class="details custom-block"><summary>装完依赖启动报 &quot;Cannot find module&quot;</summary><p>先确认三件事：<code>node_modules</code> 存在、<code>package.json</code> 里确实声明了这个包、你没在错误的目录里执行命令 （必须在有 <code>package.json</code> 的那一层）。</p></details><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>环境装好了，接着读：</p><ul><li><a href="/frontend-engineering-course/guide/roadmap.html">12 周课程地图</a> —— 看清整门课的推进节奏</li><li><a href="/frontend-engineering-course/unit01/">单元 1：工程化认知与开发环境</a> —— 从这里正式开始</li><li><a href="/frontend-engineering-course/appendix/errors.html">常见报错与排查</a> —— 收藏这一页，后面会反复用</li></ul>`,57)])])}const g=i(n,[["render",l]]);export{c as __pageData,g as default};
